def _pcg_binding_status():
    status = _pcg_raw_schema.binding_status()
    status.update(registered=False, registration_ready=False, schema_verified=False, schema_error="")
    registry = unreal.ToolsetRegistry
    if registry.is_available():
        try:
            status["registered"] = registry.is_toolset_registered(_pcg_raw_schema.TOOLSET_NAME)
            schemas = json.loads(registry.get_all_toolset_json_schemas())
            matches = [row for row in schemas if type(row) is dict and row.get("name") == _pcg_raw_schema.TOOLSET_NAME]
            if not status["registered"] or len(matches) != 1:
                raise RuntimeError("Exact owned named PCG raw4 registration required")
            status.update(_pcg_raw_schema.validate_schema(matches[0]))
        except Exception as error:
            status["schema_error"] = str(error)
    status["registration_ready"] = bool(status["bindings_ready"] and status["registered"] and status["schema_verified"])
    status["registration_verified"] = status["registration_ready"]
    status["ready"] = bool(status["registration_ready"] and status["construction_available"])
    status["execution_ready"] = False
    status["loaded_snapshot_bindings_available"] = bool(status["methods"].get("inspect_graph_snapshot"))
    status["verification_scope"] = "PCG7 registration/schema and callable presence only. Legacy general Python construction stays blocked; request-owned Native JSON graph-spec construction is reported separately, including concrete installed native PCG scalar-field profiles beyond the old fixed18. Existing class/field/owner/source/GC guards are not released. No per-request behavior or engine SDK GC repair is inferred from binding presence."
    return status


def _niagara_parameter_binding_status():
    from cubeless_mcp_ue58.compatibility.ue58.niagara_parameters import BINDINGS
    library = getattr(unreal, "CubelessNiagaraParameterLibrary", None)
    methods = [{"name": name, "callable": callable(getattr(library, name, None))} for name in BINDINGS]
    return {"python_library": "unreal.CubelessNiagaraParameterLibrary", "class_available": library is not None,
        "ready": library is not None and all(row["callable"] for row in methods), "methods": methods,
        "verification_scope": "Binding presence only; typed declarations/compiler/save behavior requires actual execution"}


def _niagara_emitter_binding_status():
    from cubeless_mcp_ue58.compatibility.ue58.niagara_emitters import BINDINGS
    library = getattr(unreal, "CubelessNiagaraEmitterLibrary", None)
    methods = [{"name": name, "callable": callable(getattr(library, name, None))} for name in BINDINGS]
    return {"python_library": "unreal.CubelessNiagaraEmitterLibrary", "class_available": library is not None,
        "ready": library is not None and all(row["callable"] for row in methods), "methods": methods,
        "verification_scope": "Binding presence only; attachment/localization/compiler/save require actual execution"}


