def _validate_graph_schema(schema):
    if type(schema) is not dict or type(schema.get("tools")) is not list:
        raise RuntimeError("Actual canonical Graph32 schema required")
    expected_tools = ('add_blueprint_is_valid_exec_macro_node', 'add_blueprint_data_table_bool_select_node', 'add_blueprint_get_data_table_row_node', 'add_blueprint_map_function_node', 'add_blueprint_loop_node', 'add_blueprint_make_array_node', 'add_blueprint_array_function_node', 'add_blueprint_break_struct_node', 'add_blueprint_event_node', 'add_blueprint_custom_event_node', 'add_blueprint_input_key_node', 'add_blueprint_parent_function_call', 'resolve_blueprint_graph', 'add_blueprint_function_parameter', 'add_blueprint_return_node', 'add_blueprint_dynamic_cast_node', 'add_blueprint_call_function_node', 'inspect_graph', 'add_branch_node', 'add_blueprint_branch_node', 'add_blueprint_sequence_node', 'set_node_position', 'delete_node', 'list_blueprint_nodes', 'delete_blueprint_node', 'connect_graph_pins', 'connect_blueprint_graph_pins', 'add_blueprint_variable_get_node', 'add_blueprint_variable_set_node', 'set_blueprint_pin_default', 'add_blueprint_make_struct_node', 'set_blueprint_custom_event_metadata')
    rows = schema["tools"]
    if len(rows) != 32 or any(type(row) is not dict or type(row.get("name")) is not str for row in rows) or {row["name"].rsplit(".", 1)[-1] for row in rows} != set(expected_tools):
        raise RuntimeError("Canonical Graph must retain prior30 tools plus original List7/Delete12")
    tools = {row["name"].rsplit(".", 1)[-1]: row["inputSchema"] for row in schema.get("tools", [])}
