def _validate_sequencer_schema(schema):
    tools = {row["name"].rsplit(".", 1)[-1]: row["inputSchema"] for row in schema.get("tools", [])}
    required = {"create_level_sequence": {"sequence_path"}, "get_level_sequence_info": {"sequence_path"},
                "add_level_sequence_actor_binding": {"sequence_path", "actor_label"},
                "add_level_sequence_transform_keys": {"sequence_path", "keys"},
                "add_level_sequence_float_property_keys": {"sequence_path", "property_path", "keys"},
                "set_level_sequence_playback_range": {"sequence_path", "playback_start_frame", "playback_end_frame"},
                "remove_level_sequence_binding": {"sequence_path"},
                "add_level_sequence_subsequence": {"sequence_path", "subsequence_path", "start_frame", "duration_frames"},
                "add_level_sequence_camera_cut": {"sequence_path", "start_frame", "end_frame"},
                "open_level_sequence_in_editor": {"sequence_path"}}
    if len(schema.get("tools", [])) != 10 or set(tools) != set(required):
        raise RuntimeError("Sequencer must expose exactly the ten migrated names")
    for name, fields in required.items():
        if set(tools[name].get("required", [])) != fields:
            raise RuntimeError(name + " changed its required inputs")
        if name not in ("get_level_sequence_info", "open_level_sequence_in_editor") and tools[name]["properties"].get("save", {}).get("default") is not True:
            raise RuntimeError(name + " changed original save=True")
    props = tools["create_level_sequence"]["properties"]
    for key, value in (("frame_rate", 30.0), ("playback_start_frame", 0.0), ("playback_end_frame", 150.0)):
        if props.get(key, {}).get("default") != value:
            raise RuntimeError("Sequencer create changed " + key)
    if tools["add_level_sequence_transform_keys"]["properties"].get("keys", {}).get("type") != "string":
        raise RuntimeError("Sequencer reflected keys must declare the implemented JSON-text representation")
    _sequencer_float_schema.validate_schema(schema)
    _sequencer_maintenance_schema.validate_schema(schema)
    _sequencer_subsequence_schema.validate_schema(schema)
    _sequencer_camera_schema.validate_schema(schema)
    _sequencer_editor_schema.validate_schema(schema)


