def _validate_async_interop_schema(schema):
    if type(schema) is not dict or type(schema.get("tools")) is not list or len(schema["tools"]) != 1:
        raise RuntimeError("CU one-tool reflected async schema required")
    row = schema["tools"][0]
    if type(row) is not dict or row.get("name", "").rsplit(".", 1)[-1] != "probe_async_operation_result":
        raise RuntimeError("CU exact no-asset probe name required")
    inputs = row.get("inputSchema")
    properties = inputs.get("properties") if type(inputs) is dict else None
    if (type(inputs) is not dict or inputs.get("type") != "object"
            or type(properties) is not dict or set(properties) != {"marker"} or inputs.get("required") != ["marker"]
            or type(properties["marker"]) is not dict or properties["marker"].get("type") != "string"
            or "default" in properties["marker"] or properties["marker"].get("nullable") is True):
        raise RuntimeError("CU required nonnullable marker string schema changed")
    output = row.get("outputSchema")
    outer_fields = output.get("properties") if type(output) is dict else None
    if (type(output) is not dict or output.get("type") != "object" or type(outer_fields) is not dict
            or set(outer_fields) != {"returnValue"} or output.get("required") != ["returnValue"]):
        raise RuntimeError("CU exact official returnValue object envelope required")
    returned = outer_fields["returnValue"]
    names = ("success", "operation_id", "stage", "error_code", "error", "changes_json", "compile_json",
             "save_json", "validation_json", "retry_json", "data_json")
    fields = returned.get("properties") if type(returned) is dict else None
    if (type(returned) is not dict or returned.get("type") != "object" or type(fields) is not dict
            or set(fields) != set(names) or set(returned.get("required", [])) != set(names)
            or len(returned.get("required", [])) != len(names)):
        raise RuntimeError("CU async Value must expose exact existing standard11 result schema")
    for name in names:
        if type(fields[name]) is not dict or fields[name].get("type") != ("boolean" if name == "success" else "string"):
            raise RuntimeError("CU async output field type changed: " + name)
    return {"schema_verified": True, "validated_input_counts": {"probe_async_operation_result": 1},
            "standard11_async_value_schema": True, "actual_probe_verified": False,
            "asset_or_shader_or_batch_behavior_verified": False}


